import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def add_resting(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return item
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None:
                o['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = top_valid(sell_heap)
                if top is None:
                    break
                sell_price, sell_seq, sell_oid = top
                if price is not None and sell_price > price:
                    break
                sell_order = book[sell_oid]
                trade_qty = min(remaining, sell_order['qty'])
                trades.append([oid, sell_oid, sell_price, trade_qty])
                remaining -= trade_qty
                sell_order['qty'] -= trade_qty
                if sell_order['qty'] <= 0:
                    sell_order['active'] = False
                    heapq.heappop(sell_heap)
        else:
            while remaining > 0:
                top = top_valid(buy_heap)
                if top is None:
                    break
                neg_price, buy_seq, buy_oid = top
                buy_price = -neg_price
                if price is not None and buy_price < price:
                    break
                buy_order = book[buy_oid]
                trade_qty = min(remaining, buy_order['qty'])
                trades.append([buy_oid, oid, buy_price, trade_qty])
                remaining -= trade_qty
                buy_order['qty'] -= trade_qty
                if buy_order['qty'] <= 0:
                    buy_order['active'] = False
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            add_resting(oid, side, price, remaining, seq)
        else:
            if oid in book:
                book[oid]['active'] = False

    return trades

